INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 2, 'paragraph',
       $b519${"text":"Несмотря на появление сотен и даже тысяч цифровых активов, Биткоин остается самой надежной и популярной криптовалютой в мире. Сложность добычи BTC стремительно увеличивается, что вынуждает производителей асиков создавать новые, более мощные и энергоэффективные модели техники. Как выглядит ТОП-10 самых мощных моделей для работы с Биткоином? Познакомимся с лидерами 2024–2025 годов.","html":"Несмотря на появление сотен и даже тысяч цифровых активов, Биткоин остается самой надежной и популярной криптовалютой в мире. Сложность добычи BTC стремительно увеличивается, что вынуждает производителей асиков создавать новые, более мощные и энергоэффективные модели техники. Как выглядит ТОП-10 самых мощных моделей для работы с Биткоином? Познакомимся с лидерами 2024–2025 годов."}$b519$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

