SELECT a.id, 5, 'paragraph',
       $b522${"text":"Существует три ключевые причины, почему именно в работе следует использовать высокопроизводительное оборудование для добычи криптовалют:","html":"Существует три ключевые причины, почему именно в работе следует использовать высокопроизводительное оборудование для добычи криптовалют:"}$b522$::jsonb,
