INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 6, 'rich_list',
       $b523${"ordered":false,"items":[{"title":"Сложность сети постоянно растет","text":"Майнинг-сети, особенно такие как Bitcoin, регулярно увеличивают свою сложность. С каждым новым участником конкуренция за блоки возрастает. Мощный асик позволяет оставаться в игре, добывать блоки и получать награды даже при растущей конкуренции;"},{"title":"Быстрая окупаемость","text":"Высокая производительность означает больше хешрейта, а значит – больше потенциальных доходов на растущем рынке. При грамотной настройке и разумной цене на электричество мощный асик может окупиться значительно быстрее, чем слабый или устаревший;"},{"title":"Более высокая стабильность","text":"Современные мощные асики часто имеют улучшенные системы охлаждения, защиты от перегрева, а также лучшую энергоэффективность, что делает работу более стабильной и предсказуемой."}]}$b523$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

