INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 8, 'list',
       $b525${"ordered":false,"items":["Высокий хешрейт – главное преимущество. Например, Antminer S21 выдает до 200–250 TH/s, а Hydro-модели доходят до 800+ TH/s;","Энергоэффективность – топовые модели работают с эффективностью около 20–30% лучше, чем более старые или слабые аналоги;","Меньше устройств – проще обслуживание. Один мощный асик может заменить три или четыре устаревших устройства, упрощая логистику и управление фермой;","Долгосрочная актуальность – такие модели дольше остаются рентабельными в условиях роста сложности и изменения курса криптовалют."]}$b525$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

