INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 10, 'list',
       $b527${"ordered":false,"items":["Высокая цена на старте – топовые модели могут стоить от $3000 до $10 000 и выше;","Большое энергопотребление – несмотря на эффективность, общая потребляемая мощность может достигать 3–6 кВт на устройство;","Шум и тепло – особенно в моделях с воздушным охлаждением. Размещение в жилом помещении затруднительно;","Инфраструктурные требования – необходимо стабильное электроснабжение, вентиляция или водяное охлаждение, защита от перегрузок."]}$b527$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

