INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 13, 'list',
       $b530${"ordered":false,"items":["Старые или менее мощные устройства. Их можно купить дешевле, но они будут быстрее устаревать и приносить меньший доход. Часто используются в регионах с дешевой или бесплатной электроэнергией;","GPU-майнинг. Гибкий вариант, особенно для монет на алгоритмах, устойчивых к асикам. Подход требует больше технической подготовки и дает меньшую прибыль при той же стоимости оборудования;","Облачный майнинг. Аренда мощностей у дата-центров. Не требует покупки оборудования, но риски высоки: от непрозрачных условий до мошенничества;","Фермы на CPU. Формат, редко используемый сегодня, подходит скорее для экспериментов или специфических алгоритмов."]}$b530$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

