INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 15, 'paragraph',
       $b532${"text":"Единственный в нашем рейтинге асик с воздушной системой охлаждения в нижней части списка — классический Antminer S21 XP на 270 терахешей является одним из самых мощных майнеров, охлаждаемых при помощи воздуха. Подобное явление можно считать показательным: производители столкнулись со сложностями при использовании традиционных систем охлаждения, учитывая феноменальную мощность современной аппаратуры.","html":"Единственный в нашем рейтинге асик с воздушной системой охлаждения в нижней части списка — классический Antminer S21 XP на 270 терахешей является одним из самых мощных майнеров, охлаждаемых при помощи воздуха. Подобное явление можно считать показательным: производители столкнулись со сложностями при использовании традиционных систем охлаждения, учитывая феноменальную мощность современной аппаратуры."}$b532$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 16, 'paragraph',
       $b533${"text":"Antminer S21 XP выполнен в традиционном для Bitmain вертикальном форм-факторе с двумя парами вентиляторов. Интерфейсы подключения, настройка и обслуживание – все это знакомо любому майнеру, использующему в своей работе асики для майнинга Биткоина. Для того чтобы добывать первую криптовалюту мира с помощью данной модели, не нужно осваивать новые технологии. Задача предельно проста и понятна.","html":"Antminer S21 XP выполнен в традиционном для Bitmain вертикальном форм-факторе с двумя парами вентиляторов. Интерфейсы подключения, настройка и обслуживание – все это знакомо любому майнеру, использующему в своей работе асики для майнинга Биткоина. Для того чтобы добывать первую криптовалюту мира с помощью данной модели, не нужно осваивать новые технологии. Задача предельно проста и понятна."}$b533$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

