INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 21, 'paragraph',
       $b538${"text":"310 терахешей оказалось недостаточно для того, чтобы оказаться в тройке самых мощных асиков в 2024 году. И в то же время этого вполне хватило для отказа производителя от традиционного воздушного принципа охлаждения. Модель Whatsminer M66S от компании MicroBT предназначена для погружения в иммерсионную жидкость – именно таким образом происходит охлаждение плат модели.","html":"310 терахешей оказалось недостаточно для того, чтобы оказаться в тройке самых мощных асиков в 2024 году. И в то же время этого вполне хватило для отказа производителя от традиционного воздушного принципа охлаждения. Модель Whatsminer M66S от компании MicroBT предназначена для погружения в иммерсионную жидкость – именно таким образом происходит охлаждение плат модели."}$b538$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 22, 'paragraph',
       $b539${"text":"Еще одна отличительная особенность аппаратуры – внушительный объем потребляемого тока, 5 580 Ватт. Тем не менее, энергоэффективность можно назвать отличной – именно так выглядит будущее майнинга Биткоина на асиках. Модель открывает новую эру добычи первой криптовалюты мира: процесс стал более сложен и требует от майнеров формирования новых навыков в области борьбы с перегревом. Но с другой стороны, иммерсионное охлаждение уже хорошо знакомо многим владельцам ферм, например, в Сибири: здесь переориентации на использование иммерсионной жидкости подвергаются даже самые привычные асики.","html":"Еще одна отличительная особенность аппаратуры – внушительный объем потребляемого тока, 5 580 Ватт. Тем не менее, энергоэффективность можно назвать отличной – именно так выглядит будущее майнинга Биткоина на асиках. Модель открывает новую эру добычи первой криптовалюты мира: процесс стал более сложен и требует от майнеров формирования новых навыков в области борьбы с перегревом. Но с другой стороны, иммерсионное охлаждение уже хорошо знакомо многим владельцам ферм, например, в Сибири: здесь переориентации на использование иммерсионной жидкости подвергаются даже самые привычные асики."}$b539$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

