INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 27, 'paragraph',
       $b544${"text":"Мощный асик от компании MicroBT на 320 терахешей выполнен в серверном форм-факторе и обладает водяной системой охлаждения. В отличие от иммерсионного принципа, WhatsMiner M53S++ не нужно погружать в специальную жидкость. Требуется несколько иной комплект дополнений, чтобы обеспечивать формирование комфортных температур – это система радиаторов и помпа. Проще говоря, чипы передают нагрев воде, которая с помощью насоса доставляется к радиатору, где и происходит рассеивание тепла.","html":"Мощный асик от компании MicroBT на 320 терахешей выполнен в серверном форм-факторе и обладает водяной системой охлаждения. В отличие от иммерсионного принципа, WhatsMiner M53S++ не нужно погружать в специальную жидкость. Требуется несколько иной комплект дополнений, чтобы обеспечивать формирование комфортных температур – это система радиаторов и помпа. Проще говоря, чипы передают нагрев воде, которая с помощью насоса доставляется к радиатору, где и происходит рассеивание тепла."}$b544$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 28, 'paragraph',
       $b545${"text":"WhatsMiner M53S++ является еще одним доказательством того факта, что будущее майнинга Биткоина строится не на воздушном, а альтернативных принципах охлаждения. Безусловно, этот подход требует дополнительных расходов (не менее 1 000 долларов), однако, только таким способом можно обеспечить охлаждение сверхпроизводительных моделей техники для BTC.","html":"WhatsMiner M53S++ является еще одним доказательством того факта, что будущее майнинга Биткоина строится не на воздушном, а альтернативных принципах охлаждения. Безусловно, этот подход требует дополнительных расходов (не менее 1 000 долларов), однако, только таким способом можно обеспечить охлаждение сверхпроизводительных моделей техники для BTC."}$b545$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

