INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 33, 'paragraph',
       $b550${"text":"Более совершенной версией M53S++ является модель следующего поколения – Whatsminer M63S. Это еще более производительный асик, мощность которого достигает 406 терахешей. Инженерам MicroBT удалось оптимизировать параметры энергоэффективности, незначительно увеличив объем потребления, но при этом серьезно разогнав мощность асика.","html":"Более совершенной версией M53S++ является модель следующего поколения – Whatsminer M63S. Это еще более производительный асик, мощность которого достигает 406 терахешей. Инженерам MicroBT удалось оптимизировать параметры энергоэффективности, незначительно увеличив объем потребления, но при этом серьезно разогнав мощность асика."}$b550$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 34, 'paragraph',
       $b551${"text":"Для охлаждения используется уже знакомый нам водяной принцип, который отлично вписывается в систему отопления загородного дома: таким образом можно решить сразу две задачи. Помимо заработка на добыче цифровых активов, это еще и снижение коммунальных платежей. Недостатки те же, что и у моделей предыдущего поколения – дополнительные расходы на организацию системы охлаждения, а также серьезные требования к электрификации помещения.","html":"Для охлаждения используется уже знакомый нам водяной принцип, который отлично вписывается в систему отопления загородного дома: таким образом можно решить сразу две задачи. Помимо заработка на добыче цифровых активов, это еще и снижение коммунальных платежей. Недостатки те же, что и у моделей предыдущего поколения – дополнительные расходы на организацию системы охлаждения, а также серьезные требования к электрификации помещения."}$b551$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

