INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 39, 'paragraph',
       $b556${"text":"Antminer S23 Immersion 442 TH/s — это мощный асик 2025 года, созданный компанией Bitmain для работы исключительно в иммерсионных системах охлаждения. Он рассчитан на крупные майнинг-площадки, где критичны эффективность, стабильность и экономия на охлаждении.","html":"Antminer S23 Immersion 442 TH/s — это мощный асик 2025 года, созданный компанией Bitmain для работы исключительно в иммерсионных системах охлаждения. Он рассчитан на крупные майнинг-площадки, где критичны эффективность, стабильность и экономия на охлаждении."}$b556$::jsonb,
