FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 40, 'paragraph',
       $b557${"text":"Хешрейт в 442 TH/s при энергоэффективности 12 J/TH делает этот майнер одним из самых производительных решений на алгоритме SHA-256. Благодаря отсутствию вентиляторов устройство работает практически бесшумно, не перегревается и выдерживает круглосуточную рабочую нагрузку без снижения производительности.","html":"Хешрейт в 442 TH/s при энергоэффективности 12 J/TH делает этот майнер одним из самых производительных решений на алгоритме SHA-256. Благодаря отсутствию вентиляторов устройство работает практически бесшумно, не перегревается и выдерживает круглосуточную рабочую нагрузку без снижения производительности."}$b557$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 41, 'paragraph',
       $b558${"text":"Для дата-центров, майнинг-ферм и крупных инвесторов Antminer S23 Imm является инструментом промышленного уровня — стойким, экономичным и созданным под долгую работу в условиях бесконечного вычислительного марафона.","html":"Для дата-центров, майнинг-ферм и крупных инвесторов Antminer S23 Imm является инструментом промышленного уровня — стойким, экономичным и созданным под долгую работу в условиях бесконечного вычислительного марафона."}$b558$::jsonb,
