SELECT a.id, 46, 'paragraph',
       $b563${"text":"Antminer S21 XP Hydro от компании BITMAIN демонстрирует феноменальные метрики производительности – 473 терахеша. Майнер использует водяную систему охлаждения, которая позволяет модели продемонстрировать все свои лучшие качества.","html":"Antminer S21 XP Hydro от компании BITMAIN демонстрирует феноменальные метрики производительности – 473 терахеша. Майнер использует водяную систему охлаждения, которая позволяет модели продемонстрировать все свои лучшие качества."}$b563$::jsonb,
