INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 47, 'paragraph',
       $b564${"text":"Также как и в случае с ближайшими конкурентами от Whatsminer, асик Antminer необходимо дополнить системой радиаторов и помпой, либо использовать ферму в качестве котла отопления индивидуального дома – все это сопряжено с дополнительными расходами. Однако если проанализировать параметры энергоэффективности, становится ясно, что перед нами – феноменальное устройство, которое позволяет добывать BTC с максимальной эффективностью.","html":"Также как и в случае с ближайшими конкурентами от Whatsminer, асик Antminer необходимо дополнить системой радиаторов и помпой, либо использовать ферму в качестве котла отопления индивидуального дома – все это сопряжено с дополнительными расходами. Однако если проанализировать параметры энергоэффективности, становится ясно, что перед нами – феноменальное устройство, которое позволяет добывать BTC с максимальной эффективностью."}$b564$::jsonb,
