INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 52, 'paragraph',
       $b569${"text":"SealMiner A2 Pro Hyd — это мощная инженерная машина, рассчитанная на долгую и стабильную работу, способную приносить прибыль даже при изменчивой экономике криптовалютного рынка. Промышленный асик нового поколения, созданный для тех, кто строит серьезную инфраструктуру для добычи Bitcoin. Хешрейт 500 TH/s открывает доступ к высокой и стабильной доходности, а гидросистема охлаждения позволяет устройству выдерживать круглосуточные нагрузки без перегрева и снижения производительности.","html":"SealMiner A2 Pro Hyd — это мощная инженерная машина, рассчитанная на долгую и стабильную работу, способную приносить прибыль даже при изменчивой экономике криптовалютного рынка. Промышленный асик нового поколения, созданный для тех, кто строит серьезную инфраструктуру для добычи Bitcoin. Хешрейт 500 TH/s открывает доступ к высокой и стабильной доходности, а гидросистема охлаждения позволяет устройству выдерживать круглосуточные нагрузки без перегрева и снижения производительности."}$b569$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

