SELECT a.id, 53, 'paragraph',
       $b570${"text":"Модель использует энергоэффективность на уровне 14,9 J/TH, что делает ее конкурентоспособной среди устройств 2025 года. При этом потребление 7450 Вт требует серьезного подхода к электрификации, особенно в условиях промышленных ферм и корпоративных дата-центров.","html":"Модель использует энергоэффективность на уровне 14,9 J/TH, что делает ее конкурентоспособной среди устройств 2025 года. При этом потребление 7450 Вт требует серьезного подхода к электрификации, особенно в условиях промышленных ферм и корпоративных дата-центров."}$b570$::jsonb,
