INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 58, 'paragraph',
       $b575${"text":"Antminer S23 Hydro — очередной шаг Bitmain к пределам вычислительной производительности. Эта модель создана для промышленного майнинга в условиях растущей конкуренции и усложняющейся добычи Bitcoin. С хешрейтом 580 TH/s и энергоэффективностью 9.5 J/TH асик уверенно входит в число самых технологичных решений 2025 года.","html":"Antminer S23 Hydro — очередной шаг Bitmain к пределам вычислительной производительности. Эта модель создана для промышленного майнинга в условиях растущей конкуренции и усложняющейся добычи Bitcoin. С хешрейтом 580 TH/s и энергоэффективностью 9.5 J/TH асик уверенно входит в число самых технологичных решений 2025 года."}$b575$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 59, 'paragraph',
       $b576${"text":"Секрет стабильной работы — водяное охлаждение, позволяющее избежать перегрева, продлить срок службы чипов и минимизировать потери производительности при круглосуточной нагрузке. Потребляемая мощность составляет 5510 Вт, что делает устройство удивительно экономичным для такого уровня хешрейта — особенно в сравнении с предыдущими поколениями.","html":"Секрет стабильной работы — водяное охлаждение, позволяющее избежать перегрева, продлить срок службы чипов и минимизировать потери производительности при круглосуточной нагрузке. Потребляемая мощность составляет 5510 Вт, что делает устройство удивительно экономичным для такого уровня хешрейта — особенно в сравнении с предыдущими поколениями."}$b576$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 60, 'paragraph',
       $b577${"text":"Antminer S23 Hydro — это не просто майнер, а масштабируемое промышленное решение, рассчитанное на большие фермы, дата-центры и инфраструктуру будущего Bitcoin-майнинга.","html":"Antminer S23 Hydro — это не просто майнер, а масштабируемое промышленное решение, рассчитанное на большие фермы, дата-центры и инфраструктуру будущего Bitcoin-майнинга."}$b577$::jsonb,
