INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 65, 'paragraph',
       $b582${"text":"Bitmain продолжает задавать темп в индустрии майнинга, выпуская устройства с все более высокой производительностью и энергоэффективностью. Одной из новинок стала модель Antminer S21E XP Hydro – водяной ASIC нового поколения, ориентированный на промышленные майнинг-фермы и дата-центры.","html":"Bitmain продолжает задавать темп в индустрии майнинга, выпуская устройства с все более высокой производительностью и энергоэффективностью. Одной из новинок стала модель Antminer S21E XP Hydro – водяной ASIC нового поколения, ориентированный на промышленные майнинг-фермы и дата-центры."}$b582$::jsonb,
