SELECT a.id, 66, 'paragraph',
       $b583${"text":"Antminer S21E XP Hydro способен выдавать до 860 TH/s, что делает его одним из самых мощных устройств на рынке для майнинга на алгоритме SHA-256.","html":"Antminer S21E XP Hydro способен выдавать до 860 TH/s, что делает его одним из самых мощных устройств на рынке для майнинга на алгоритме SHA-256."}$b583$::jsonb,
