INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 67, 'paragraph',
       $b584${"text":"Одним из главных преимуществ этой модели является энергоэффективность – 13 Вт/TH, что значительно ниже по сравнению с предыдущими поколениями. Это снижает эксплуатационные расходы и делает устройство более прибыльным в долгосрочной перспективе, особенно при высокой стоимости электроэнергии. S21E XP Hydro использует систему жидкостного охлаждения, что позволяет эффективно отводить тепло при высоких нагрузках.","html":"Одним из главных преимуществ этой модели является энергоэффективность – 13 Вт/TH, что значительно ниже по сравнению с предыдущими поколениями. Это снижает эксплуатационные расходы и делает устройство более прибыльным в долгосрочной перспективе, особенно при высокой стоимости электроэнергии. S21E XP Hydro использует систему жидкостного охлаждения, что позволяет эффективно отводить тепло при высоких нагрузках."}$b584$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 68, 'paragraph',
       $b585${"text":"Благодаря этому устройство работает более стабильно, не перегревается и практически не шумит, в отличие от традиционных моделей с воздушным охлаждением.","html":"Благодаря этому устройство работает более стабильно, не перегревается и практически не шумит, в отличие от традиционных моделей с воздушным охлаждением."}$b585$::jsonb,
