INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 69, 'paragraph',
       $b586${"text":"Модель выполнена в компактном форм-факторе 3U, что делает ее удобной для размещения в серверных стойках. Однако следует учитывать, что для ее полноценной работы требуется внешняя водяная система охлаждения, что увеличивает общие затраты на установку и обслуживание.","html":"Модель выполнена в компактном форм-факторе 3U, что делает ее удобной для размещения в серверных стойках. Однако следует учитывать, что для ее полноценной работы требуется внешняя водяная система охлаждения, что увеличивает общие затраты на установку и обслуживание."}$b586$::jsonb,
