INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 74, 'paragraph',
       $b591${"text":"Antminer U3S23H — самый мощный асик в линейке Bitmain, созданный для индустриального майнинга Bitcoin в условиях растущей сложности сети. С хешрейтом 1160 TH/s, он заметно опережает предыдущие поколения и формирует новый стандарт эффективности в SHA-256-сегменте.","html":"Antminer U3S23H — самый мощный асик в линейке Bitmain, созданный для индустриального майнинга Bitcoin в условиях растущей сложности сети. С хешрейтом 1160 TH/s, он заметно опережает предыдущие поколения и формирует новый стандарт эффективности в SHA-256-сегменте."}$b591$::jsonb,
       NULL
