INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 75, 'paragraph',
       $b592${"text":"Модель оснащена продвинутой системой водяного охлаждения и защищена от влаги и пыли, что обеспечивает стабильную круглосуточную работу без снижения производительности. Реализована поддержка мониторинга в реальном времени — майнер позволяет отслеживать хешрейт, параметры температуры и состояние работы оборудования без задержек, что особенно важно для крупных ферм и дата-центров.","html":"Модель оснащена продвинутой системой водяного охлаждения и защищена от влаги и пыли, что обеспечивает стабильную круглосуточную работу без снижения производительности. Реализована поддержка мониторинга в реальном времени — майнер позволяет отслеживать хешрейт, параметры температуры и состояние работы оборудования без задержек, что особенно важно для крупных ферм и дата-центров."}$b592$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'samye-moshhnye-asiki-dlya-majninga-bitkoinov-v-2024-godu-top-5';

