INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 81, 'paragraph',
       $b598${"text":"Мощные асики сегодня – это инструмент для серьезного майнинга с расчетом на долгосрочную прибыль. Они обеспечивают высокий доход и устойчивость к росту сложности сети, но требуют больших вложений и продуманной инфраструктуры. Если вы готовы инвестировать в оборудование и у вас есть доступ к недорогому электричеству – такие устройства станут основой прибыльного майнинга. В противном случае стоит рассмотреть альтернативы или вход на рынок с более скромных позиций.","html":"Мощные асики сегодня – это инструмент для серьезного майнинга с расчетом на долгосрочную прибыль. Они обеспечивают высокий доход и устойчивость к росту сложности сети, но требуют больших вложений и продуманной инфраструктуры. Если вы готовы инвестировать в оборудование и у вас есть доступ к недорогому электричеству – такие устройства станут основой прибыльного майнинга. В противном случае стоит рассмотреть альтернативы или вход на рынок с более скромных позиций."}$b598$::jsonb,
