INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 2, 'paragraph',
       $b600${"text":"Дешевые видеокарты для майнинга остаются актуальными при условии относительно недорогого электричества даже в 2024–2025 годах. Если стоимость киловатта не превышает пяти рублей, некоторые бюджетные модели способны добывать криптовалюту с положительной доходностью: узнаем, какие модификации можно использовать для майнинга из сегмента недорогих GPU.","html":"Дешевые видеокарты для майнинга остаются актуальными при условии относительно недорогого электричества даже в 2024–2025 годах. Если стоимость киловатта не превышает пяти рублей, некоторые бюджетные модели способны добывать криптовалюту с положительной доходностью: узнаем, какие модификации можно использовать для майнинга из сегмента недорогих GPU."}$b600$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

