INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 6, 'list',
       $b604${"ordered":false,"items":["Гибкость. Видеокарты поддерживают сразу несколько алгоритмов, что позволяет переключаться между монетами в зависимости от прибыльности;","Доступность. GPU можно купить в рознице или на вторичном рынке – это проще, чем найти актуальный асик;","Универсальность. Карты используются не только в майнинге – их можно задействовать для рендеринга, игр или ИИ-вычислений;","Низкий порог входа. Для старта достаточно одной-двух карт и базовых навыков сборки ПК;","Мобильность и масштабируемость. GPU-фермы проще транспортировать, модернизировать или масштабировать по мере роста доходов."]}$b604$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

