INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 10, 'list',
       $b608${"ordered":false,"items":["Возможность майнить разные монеты. В отличие от асиков, которые работают только на одном алгоритме, видеокарты можно использовать для добычи десятков криптовалют: Ethereum Classic (ETC), Kaspa, Ravencoin, Ergo, Conflux, Iron Fish и других;","Простота апгрейда. Майнер может обновить ферму, заменив лишь часть оборудования. Для этого не нужно покупать новое специализированное устройство;","Ликвидность и вторичное использование. При выходе из майнинга видеокарты легко продать или использовать по назначению. Это снижает инвестиционные риски;","Низкий уровень шума и тепла. Одиночные или небольшие GPU-фермы производят меньше шума и тепла, чем ASIC, что делает их удобными для домашнего использования."]}$b608$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

