INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 13, 'list',
       $b611${"ordered":false,"items":["Низкая энергоэффективность. GPU уступают асикам по показателю «доход на ватт». Это значит, что при одинаковом потреблении электроэнергии карты принесут меньше прибыли;","Высокая зависимость от курса монет. После перехода Ethereum на Proof-of-Stake, рынок GPU-майнинга лишился главной доходной монеты. Альтернативные монеты остаются менее прибыльными и более волатильными;","Большое внимание к обслуживанию. Видеокарты требуют ухода: нужно следить за температурой, чистить от пыли, следить за стабильностью драйверов и ОС;","Износ оборудования. Работа на высоких нагрузках ускоряет деградацию видеопамяти и вентилятора. Особенно у карт с GDDR6X и нестабильным охлаждением;","Ограничения по масштабируемости. Домашние фермы ограничены по электропитанию (обычно 3-5 кВт), что не позволяет развить крупный майнинговый проект без переезда на хостинг."]}$b611$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

