INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 15, 'paragraph',
       $b613${"text":"GPU-майнинг основан на выполнении графических вычислений для подтверждения блоков в сети криптовалют. Большинство современных майнеров используют программы вроде TeamRedMiner, LolMiner, T-Rex, NBMiner, с настройкой через конфиги и автозапуск. Для анализа прибыльности используются сайты вроде WhatToMine, Hashrate.no или калькуляторы на профильных ресурсах.","html":"GPU-майнинг основан на выполнении графических вычислений для подтверждения блоков в сети криптовалют. Большинство современных майнеров используют программы вроде TeamRedMiner, LolMiner, T-Rex, NBMiner, с настройкой через конфиги и автозапуск. Для анализа прибыльности используются сайты вроде WhatToMine, Hashrate.no или калькуляторы на профильных ресурсах."}$b613$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 16, 'paragraph',
       $b614${"text":"Процесс требует настройки BIOS, прошивок и оптимизации энергопотребления (Undervolt), особенно для максимизации прибыли и продления срока службы оборудования.","html":"Процесс требует настройки BIOS, прошивок и оптимизации энергопотребления (Undervolt), особенно для максимизации прибыли и продления срока службы оборудования."}$b614$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

