INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 18, 'paragraph',
       $b616${"text":"Самая старая и одна из наиболее дешевых видеокарт для майнинга в нашем рейтинге. Объем памяти данной GPU составляет всего 4 Гб, что делает работу в области добычи криптовалют крайне ограниченной. Скромная производительность допускает майнинг лишь считанного числа монет, что является ключевой особенностью модификации. Однако низкая стоимость компенсирует этот недостаток.","html":"Самая старая и одна из наиболее дешевых видеокарт для майнинга в нашем рейтинге. Объем памяти данной GPU составляет всего 4 Гб, что делает работу в области добычи криптовалют крайне ограниченной. Скромная производительность допускает майнинг лишь считанного числа монет, что является ключевой особенностью модификации. Однако низкая стоимость компенсирует этот недостаток."}$b616$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 19, 'paragraph',
       $b617${"text":"Видеокарта Radeon R9 380 появилась на свет в далеком 2015 году, поэтому найти достойный экземпляр сегодня непросто. Кроме того, отпугнуть потенциальных покупателей может большой для моделей этого класса объем потребляемой электроэнергии – КПД в данном отношении сложно назвать образцовым. Покупать GPU специально для майнинга невыгодно: работа допустима в случае, если данная карта имелась в вашем распоряжении заранее.","html":"Видеокарта Radeon R9 380 появилась на свет в далеком 2015 году, поэтому найти достойный экземпляр сегодня непросто. Кроме того, отпугнуть потенциальных покупателей может большой для моделей этого класса объем потребляемой электроэнергии – КПД в данном отношении сложно назвать образцовым. Покупать GPU специально для майнинга невыгодно: работа допустима в случае, если данная карта имелась в вашем распоряжении заранее."}$b617$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

