INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 24, 'paragraph',
       $b622${"text":"Простые видеокарты бюджетного сегмента некогда активно использовались для добычи криптовалют, однако, с увеличением сложности и роста хэшрейта многие модели утратили актуальность. Одним из примеров, балансирующим на грани рентабельности, является GeForce GTX 1050 Ti. Карта появилась на свет в 2016 году и долгое время была очень популярной как среди геймеров, так и майнеров. Причин несколько – низкая стоимость, хорошая энергоэффективность и относительно низкие температуры работы, чем славится продукция GeForce.","html":"Простые видеокарты бюджетного сегмента некогда активно использовались для добычи криптовалют, однако, с увеличением сложности и роста хэшрейта многие модели утратили актуальность. Одним из примеров, балансирующим на грани рентабельности, является GeForce GTX 1050 Ti. Карта появилась на свет в 2016 году и долгое время была очень популярной как среди геймеров, так и майнеров. Причин несколько – низкая стоимость, хорошая энергоэффективность и относительно низкие температуры работы, чем славится продукция GeForce."}$b622$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 25, 'paragraph',
       $b623${"text":"Сегодня на GeForce GTX 1050 Ti работает лишь небольшой объем майнеров, так как добыча криптовалют с помощью этого устройства требует знаний и опыта. Прежде всего, GPU следует разогнать для повышения хэшрейта. Во-вторых, необходим постоянный мониторинг монет с целью поиска доходной связки. В противном случае добыча с использованием этой модели становится малорентабельной.","html":"Сегодня на GeForce GTX 1050 Ti работает лишь небольшой объем майнеров, так как добыча криптовалют с помощью этого устройства требует знаний и опыта. Прежде всего, GPU следует разогнать для повышения хэшрейта. Во-вторых, необходим постоянный мониторинг монет с целью поиска доходной связки. В противном случае добыча с использованием этой модели становится малорентабельной."}$b623$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

