INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 30, 'paragraph',
       $b628${"text":"Эта недорогая видеокарта бюджетного уровня способна работать с положительной доходностью во время майнинга далеко не всех монет. Причина – небольшой хэшрейт и скромный объем памяти. Данная GPU является порогом рентабельности, поэтому широкого распространения сегодня GeForce GTX 1660 не получила. В линейке поколения есть еще две версии, однако, их стоимость выше.","html":"Эта недорогая видеокарта бюджетного уровня способна работать с положительной доходностью во время майнинга далеко не всех монет. Причина – небольшой хэшрейт и скромный объем памяти. Данная GPU является порогом рентабельности, поэтому широкого распространения сегодня GeForce GTX 1660 не получила. В линейке поколения есть еще две версии, однако, их стоимость выше."}$b628$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 31, 'paragraph',
       $b629${"text":"Технические характеристики данной карты соответствуют классу техники – здесь нет выдающихся показателей производительности, хэшрейта, нагрева и уровня шума. Приобретать модель специально для майнинга не рекомендуется: работа с ней на крипто-рынке актуальна только в том случае, если GPU ранее использовалась для игровых целей.","html":"Технические характеристики данной карты соответствуют классу техники – здесь нет выдающихся показателей производительности, хэшрейта, нагрева и уровня шума. Приобретать модель специально для майнинга не рекомендуется: работа с ней на крипто-рынке актуальна только в том случае, если GPU ранее использовалась для игровых целей."}$b629$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

