INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 36, 'paragraph',
       $b634${"text":"Классический представитель сегмента недорогих видеокарт одинаково популярен как среди геймеров, так и в майнинг-индустрии. При относительно низкой стоимости GPU демонстрирует неплохие показатели производительности, а также потенциал системы охлаждения и возможность безопасного разгона. В сегменте добычи криптовалют AMD Radeon RX 5500 XT 8GB более выгодна, чем ряд более именитых и дорогостоящих аналогов, что привлекает внимание майнеров.","html":"Классический представитель сегмента недорогих видеокарт одинаково популярен как среди геймеров, так и в майнинг-индустрии. При относительно низкой стоимости GPU демонстрирует неплохие показатели производительности, а также потенциал системы охлаждения и возможность безопасного разгона. В сегменте добычи криптовалют AMD Radeon RX 5500 XT 8GB более выгодна, чем ряд более именитых и дорогостоящих аналогов, что привлекает внимание майнеров."}$b634$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 37, 'paragraph',
       $b635${"text":"Без недостатков также не обходится – достаточно высокий уровень шума, скромный хэшрейт, а также «сырое» программное обеспечение. Зато уровень энергопотребления не превышает 100 Ватт даже во время добычи «тяжелых» монет. Это одно из лучших предложений с точки зрения энергоэффективности в классе.","html":"Без недостатков также не обходится – достаточно высокий уровень шума, скромный хэшрейт, а также «сырое» программное обеспечение. Зато уровень энергопотребления не превышает 100 Ватт даже во время добычи «тяжелых» монет. Это одно из лучших предложений с точки зрения энергоэффективности в классе."}$b635$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

