INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 41, 'paragraph',
       $b639${"text":"Данную модель GPU можно назвать популярной и узнаваемой, так как многие геймеры используют эту карту для компьютерных игр с 2017 года. Существуют версии на 4 Гб и 8 Гб памяти: для добычи криптовалют сегодня пригодна только старшая модификация – это одна из самых дешевых видеокарт для майнинга из бюджетного сегмента. Стоимость в 2024 году стартует с отметки 4 000 рублей, а суточная доходность составляет около 20 центов.","html":"Данную модель GPU можно назвать популярной и узнаваемой, так как многие геймеры используют эту карту для компьютерных игр с 2017 года. Существуют версии на 4 Гб и 8 Гб памяти: для добычи криптовалют сегодня пригодна только старшая модификация – это одна из самых дешевых видеокарт для майнинга из бюджетного сегмента. Стоимость в 2024 году стартует с отметки 4 000 рублей, а суточная доходность составляет около 20 центов."}$b639$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 42, 'paragraph',
       $b640${"text":"Хэшрейт AMD Radeon RX 580 8GB даже при разгоне сложно назвать оптимальным для майнинга – некоторые ранние модели и аналоги демонстрируют более внушительные показатели производительности. Однако майнеров привлекает мощная система охлаждения и запасные вентиляторы в комплекте (от некоторых производителей), что позволяет демонстрировать определенный потенциал при разгоне в сегменте добычи криптовалют.","html":"Хэшрейт AMD Radeon RX 580 8GB даже при разгоне сложно назвать оптимальным для майнинга – некоторые ранние модели и аналоги демонстрируют более внушительные показатели производительности. Однако майнеров привлекает мощная система охлаждения и запасные вентиляторы в комплекте (от некоторых производителей), что позволяет демонстрировать определенный потенциал при разгоне в сегменте добычи криптовалют."}$b640$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

