INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 47, 'paragraph',
       $b645${"text":"Майнинг на видеокартах – это удобный и гибкий способ добычи криптовалют, особенно для начинающих майнеров или тех, кто предпочитает универсальность и контроль. Однако с уходом Ethereum в 2022 году рынок GPU-майнинга значительно сузился. Сегодня для его рентабельности необходимо тщательно подходить к выбору монеты, конфигурации оборудования и энерготарифов.","html":"Майнинг на видеокартах – это удобный и гибкий способ добычи криптовалют, особенно для начинающих майнеров или тех, кто предпочитает универсальность и контроль. Однако с уходом Ethereum в 2022 году рынок GPU-майнинга значительно сузился. Сегодня для его рентабельности необходимо тщательно подходить к выбору монеты, конфигурации оборудования и энерготарифов."}$b645$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 48, 'paragraph',
       $b646${"text":"Если вы рассматриваете майнинг как хобби или как часть диверсифицированного криптопортфеля – видеокарты станут отличной отправной точкой. Но для построения масштабного бизнеса с минимальной себестоимостью стоит рассматривать асики, а также хостинг в регионах с дешевой электроэнергией.","html":"Если вы рассматриваете майнинг как хобби или как часть диверсифицированного криптопортфеля – видеокарты станут отличной отправной точкой. Но для построения масштабного бизнеса с минимальной себестоимостью стоит рассматривать асики, а также хостинг в регионах с дешевой электроэнергией."}$b646$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'top-5-samye-deshevye-videokarty-dlya-majninga-v-2024-godu-rejting-i-czeny';

