INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 5, 'paragraph',
       $b651${"text":"Майнинг – это не просто подключение оборудования и ожидание прибыли. Успешная стратегия требует системного подхода: учитываются технические, экономические и рыночные параметры. Одной из самых частых ошибок становится добыча «на слух» – без предварительного анализа. Это чревато убытками из-за высокой конкуренции, неокупаемых затрат на электричество и недостаточной ликвидности выбранной монеты.","html":"Майнинг – это не просто подключение оборудования и ожидание прибыли. Успешная стратегия требует системного подхода: учитываются технические, экономические и рыночные параметры. Одной из самых частых ошибок становится добыча «на слух» – без предварительного анализа. Это чревато убытками из-за высокой конкуренции, неокупаемых затрат на электричество и недостаточной ликвидности выбранной монеты."}$b651$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

