INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 11, 'rich_list',
       $b657${"ordered":false,"items":[{"title":"Тип алгоритма","text":"Каждая криптовалюта базируется на определенном алгоритме консенсуса. От него зависит, каким оборудованием ее можно добывать. Наиболее распространенные: SHA-256 – Bitcoin и производные (Bitcoin Cash и др.); Scrypt – Litecoin, Dogecoin; EtHash – Ethereum Classic; KawPow / ProgPow / RandomX – монеты, устойчивые к асикам и ориентированные на GPU. Тип алгоритма определяет совместимость с оборудованием, энергопотребление и уровень сложности майнинга;"},{"title":"Хешрейт и сложность сети","text":"Хешрейт показывает совокупную вычислительную мощность, направленную на добычу конкретной криптовалюты. Чем выше этот показатель, тем сложнее конкурировать. Однако высокая сложность не всегда означает низкую прибыль: при росте цены монеты она может компенсироваться;"},{"title":"Вознаграждение за блок","text":"Размер награды влияет на доход майнеров. Также важно учитывать, проводится ли халвинг (сокращение награды с определенной периодичностью), как у Bitcoin, или награда остается фиксированной;"},{"title":"Рыночная цена и объем торгов","text":"Даже технически перспективная монета может оказаться невыгодной, если у нее нет достаточной ликвидности. Ключевые критерии здесь – объемы на биржах, стабильность курса и наличие спроса;"},{"title":"Энергетические затраты","text":"Рентабельность зависит от стоимости электроэнергии. Например, при тарифе 6 руб/кВт⋅ч и более рентабельность майнинга большинства популярных монет существенно падает. Энергозатратные алгоритмы (как SHA-256) требуют особенно дешевого электричества;"},{"title":"Репутация проекта","text":"Важно понимать, кто стоит за разработкой, насколько активно развивается экосистема и поддерживается ли проект сообществом. Монеты без технической поддержки быстро теряют ценность."}]}$b657$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

