INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 16, 'rich_list',
       $b662${"ordered":false,"items":[{"title":"Асики","text":"ASIC (Application-Specific Integrated Circuit) – это устройства, оптимизированные под определенный алгоритм. Они характеризуются высокой производительностью, но лишены гибкости. Асики обеспечивают максимальную эффективность, но требуют стабильной инфраструктуры и низких цен на электроэнергию;"},{"title":"GPU-фермы","text":"Майнинг на видеокартах (GPU) более универсален. Один и тот же риг может добывать десятки монет, переключаясь между ними в зависимости от доходности. GPU-майнинг подходит для тех, кто ценит гибкость и планирует активную оптимизацию стратегии."}]}$b662$::jsonb,
