INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 28, 'list',
       $b674${"ordered":false,"items":["Регулярно пересматривайте текущую монету. Изменения в курсе, сложности или наградах могут резко снизить доходность;","Используйте мультипулы или автоалгоритмы. Они позволяют автоматически переключаться на самые прибыльные монеты;","Следите за прошивками и оптимизациями. Обновления прошивок асиков могут значительно повысить доходность или снизить потребление;","Работайте с проверенными пулами. Надежный пул снижает риски недополучения вознаграждений;","Рассматривайте возможность долгосрочного холдинга. Иногда разумнее не продавать добытую монету сразу, а дождаться благоприятного курса."]}$b674$::jsonb,
