INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 31, 'paragraph',
       $b677${"text":"Если инвестор принимает решение работать с мемкоинами, DOGE представляет собой наиболее защищенный вариант. Сами по себе мемы отличаются повышенной волатильностью и существующей вероятностью обесценивания, но в случае с Dogecoin ситуация более стабильна по трем причинам. Во-первых, это самый известный и старейший мемкоин, знакомый каждому. Во-вторых, проект имеет мощную поддержку со стороны комьюнити, включая интерес со стороны Илона Маска. В-третьих, капитализация: уже не первый год DOGE входит в ТОП-15 криптовалют по объему вложенных средств.","html":"Если инвестор принимает решение работать с мемкоинами, DOGE представляет собой наиболее защищенный вариант. Сами по себе мемы отличаются повышенной волатильностью и существующей вероятностью обесценивания, но в случае с Dogecoin ситуация более стабильна по трем причинам. Во-первых, это самый известный и старейший мемкоин, знакомый каждому. Во-вторых, проект имеет мощную поддержку со стороны комьюнити, включая интерес со стороны Илона Маска. В-третьих, капитализация: уже не первый год DOGE входит в ТОП-15 криптовалют по объему вложенных средств."}$b677$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 32, 'paragraph',
       $b678${"text":"В 2026-м Dogecoin имеет все шансы на успех, а особенно после принятия спотового Ethereum-ETF: это может стать триггером взрывного роста многих альтов, и мемкоин DOGE – один из первых кандидатов. Кроме того не исключена помощь со стороны Илона Маска, один только твит которого способен привести к росту курса Dogecoin на 10-15% в течение часа.","html":"В 2026-м Dogecoin имеет все шансы на успех, а особенно после принятия спотового Ethereum-ETF: это может стать триггером взрывного роста многих альтов, и мемкоин DOGE – один из первых кандидатов. Кроме того не исключена помощь со стороны Илона Маска, один только твит которого способен привести к росту курса Dogecoin на 10-15% в течение часа."}$b678$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

