INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 37, 'paragraph',
       $b683${"text":"Какая криптовалюта в 2026 году из нашего рейтинга может называться наиболее противоречивой и рискованной? Это проект ZCash и его токен ZEC. Главной особенностью сети является высокая степень анонимности: узнать участника транзакции и переводимую сумму затруднительно, что делает ZEC оптимальным активом для проведения сомнительных операций в даркнете. Это и недостаток и преимущество продукта, что является главной причиной множества противоречий.","html":"Какая криптовалюта в 2026 году из нашего рейтинга может называться наиболее противоречивой и рискованной? Это проект ZCash и его токен ZEC. Главной особенностью сети является высокая степень анонимности: узнать участника транзакции и переводимую сумму затруднительно, что делает ZEC оптимальным активом для проведения сомнительных операций в даркнете. Это и недостаток и преимущество продукта, что является главной причиной множества противоречий."}$b683$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 38, 'paragraph',
       $b684${"text":"С одной стороны многие регуляторы сегодня стремятся сделать крипторынок прозрачным и контролируемым: такие проекты, как ZCash явно не вписываются в указанную концепцию. Итог: многие биржи и проекты уже отказались от работы с ZEC, что невыгодно для пользователей. Но с другой стороны, если вы желаете сохранить практически полную анонимность, блокчейн может стать отличным решением. А еще ZEC можно майнить на алгоритме Proof of Work: хешрейт сети стабилен и не поддается негативу новостного фона. Такая поддержка со стороны майнеров может привести к росту курса ZCash в 2026 году.","html":"С одной стороны многие регуляторы сегодня стремятся сделать крипторынок прозрачным и контролируемым: такие проекты, как ZCash явно не вписываются в указанную концепцию. Итог: многие биржи и проекты уже отказались от работы с ZEC, что невыгодно для пользователей. Но с другой стороны, если вы желаете сохранить практически полную анонимность, блокчейн может стать отличным решением. А еще ZEC можно майнить на алгоритме Proof of Work: хешрейт сети стабилен и не поддается негативу новостного фона. Такая поддержка со стороны майнеров может привести к росту курса ZCash в 2026 году."}$b684$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

