INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 42, 'paragraph',
       $b688${"text":"Лайткоин появился на свет в 2011 году как «облегченная» версия BTC с устраненными недостатками. Несмотря на то, что с тех пор прошло уже более 10 лет, LTC так и не сумел обойти своего старшего брата, однако, в ТОП-25 крупнейших по капитализации монет входит исправно. Это надежный актив с хорошей репутацией без негативных историй и громких скандалов.","html":"Лайткоин появился на свет в 2011 году как «облегченная» версия BTC с устраненными недостатками. Несмотря на то, что с тех пор прошло уже более 10 лет, LTC так и не сумел обойти своего старшего брата, однако, в ТОП-25 крупнейших по капитализации монет входит исправно. Это надежный актив с хорошей репутацией без негативных историй и громких скандалов."}$b688$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 43, 'paragraph',
       $b689${"text":"Причин, почему интересна данная криптовалюта, несколько. Во-первых, это состоявшийся в августе 2023 года халвинг Litecoin: размер награды за блок снижен вдвое, а это значит, что актив стал еще более дефицитным (особенно если учесть его ограниченную эмиссию). Во-вторых, растущая сложность майнинга – здесь ситуация аналогична BTC. Раз растет сложность, значит майнеры видят перспективы монеты и планируют дальше инвестировать в ее добычу. В-третьих, это возможность одновременного майнинга LTC и второго актива – Dogecoin. Еще одно преимущество в копилку популярности у майнеров и жирный плюс в перспективы роста.","html":"Причин, почему интересна данная криптовалюта, несколько. Во-первых, это состоявшийся в августе 2023 года халвинг Litecoin: размер награды за блок снижен вдвое, а это значит, что актив стал еще более дефицитным (особенно если учесть его ограниченную эмиссию). Во-вторых, растущая сложность майнинга – здесь ситуация аналогична BTC. Раз растет сложность, значит майнеры видят перспективы монеты и планируют дальше инвестировать в ее добычу. В-третьих, это возможность одновременного майнинга LTC и второго актива – Dogecoin. Еще одно преимущество в копилку популярности у майнеров и жирный плюс в перспективы роста."}$b689$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

