SELECT a.id, 46, 'pros_cons',
       $b692${"pros":["Старая и проверенная монета;","Litecoin можно добывать на видеокартах и асиках;","Возможность дуал-майнинга: добыча LTC вместе с DOGE;","В 2023 году состоялся халвинг: актив стал более дефицитным, а ситуация с наградами майнинга останется неизменной еще 4 года;","Сложность майнинга Лайткоин растет: в сфере появляются новые инвесторы, как и в случае с сетью BTC. Это значит, что майнеры верят в проект;","Ограниченная эмиссия – эффект искусственного дефицита."],"cons":["Litecoin уступает конкурентам по интенсивности развития и внедрению новых решений;","Многие считают, что время LTC уже ушло."]}$b692$::jsonb,
