INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 48, 'paragraph',
       $b694${"text":"Стремительная интеграция с Telegram, активное участие Павла Дурова и его команды, рекорды скорости обработки транзакций – речь идет о сети The Open Network, которая обладает внушительными перспективами развития. Многие заявляют, что именно эта криптовалюта в 2024 году является темной лошадкой, ожидать от которой можно наиболее ощутимого роста. Даже если отбросить эти смелые прогнозы, трудно не согласиться с тем фактом, что интерес разработчиков и инвесторов к Toncoin стремительно увеличивается.","html":"Стремительная интеграция с Telegram, активное участие Павла Дурова и его команды, рекорды скорости обработки транзакций – речь идет о сети The Open Network, которая обладает внушительными перспективами развития. Многие заявляют, что именно эта криптовалюта в 2024 году является темной лошадкой, ожидать от которой можно наиболее ощутимого роста. Даже если отбросить эти смелые прогнозы, трудно не согласиться с тем фактом, что интерес разработчиков и инвесторов к Toncoin стремительно увеличивается."}$b694$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 49, 'paragraph',
       $b695${"text":"Число сервисов на TON растет, а в конце 2023 года сеть The Open Network установила рекорд по скорости работы среди всех современных блокчейнов. Также TON можно добывать с помощью майнинга – именно в таком формате работает проект Cocoon Павла Дурова.","html":"Число сервисов на TON растет, а в конце 2023 года сеть The Open Network установила рекорд по скорости работы среди всех современных блокчейнов. Также TON можно добывать с помощью майнинга – именно в таком формате работает проект Cocoon Павла Дурова."}$b695$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

