SELECT a.id, 51, 'pros_cons',
       $b697${"pros":["Один из наиболее динамично развивающихся блокчейнов;","Поддержка Павла Дурова и его команды;","Ограниченная эмиссия и как следствие – эффект искусственного дефицита;","Рекордная скорость работы сети;","Повышенный интерес разработчиков приложений и инструментов к платформе The Open Network;","Майнинг в рамках проекта Cocoon."],"cons":["Ограничения со стороны SEC;","Молодой проект, не обладающий репутацией проверенного контрагента с богатой историей;","Поддержка не всех площадок и бирж."]}$b697$::jsonb,
