INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 53, 'paragraph',
       $b699${"text":"Когда-то монету SOL называли «убийцей» Эфира, однако, крах биржи FTX (основного инвестора сети) несколько подорвал репутацию блокчейна Solana. Тем не менее, Солана справилась с негативом и сумела полностью восстановиться после данного события, что открывает неплохие перспективы для роста. По капитализации, объемам торгов и интересу со стороны инвесторов SOL еще далеко до ETH, но именно это может являться потенциалом для роста актива. Тем более, на базе Solana создаются многочисленные NFT-коллекции и мемы, что является сильной стороной платформы.","html":"Когда-то монету SOL называли «убийцей» Эфира, однако, крах биржи FTX (основного инвестора сети) несколько подорвал репутацию блокчейна Solana. Тем не менее, Солана справилась с негативом и сумела полностью восстановиться после данного события, что открывает неплохие перспективы для роста. По капитализации, объемам торгов и интересу со стороны инвесторов SOL еще далеко до ETH, но именно это может являться потенциалом для роста актива. Тем более, на базе Solana создаются многочисленные NFT-коллекции и мемы, что является сильной стороной платформы."}$b699$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 54, 'paragraph',
       $b700${"text":"Сегодня Солану можно назвать не «убийцей» Эфириума, а его недооцененной (и пока не настолько технологичной) копией. Проект пережил крах FTX, а по оценкам некоторых экспертов рано или поздно курс SOL может достигнуть 3 200 долларов США. Исходя из этого ответом на вопрос, какая криптовалюта в 2026 году наиболее недооценена, вполне может стать Solana.","html":"Сегодня Солану можно назвать не «убийцей» Эфириума, а его недооцененной (и пока не настолько технологичной) копией. Проект пережил крах FTX, а по оценкам некоторых экспертов рано или поздно курс SOL может достигнуть 3 200 долларов США. Исходя из этого ответом на вопрос, какая криптовалюта в 2026 году наиболее недооценена, вполне может стать Solana."}$b700$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

