INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 56, 'pros_cons',
       $b702${"pros":["Вхождение в ТОП-5 криптовалют 2024 года по капитализации;","Монета сумела восстановиться после краха биржи FTX;","Высокая скорость работы сети;","Минимальные комиссии;","Популярность NFT-коллекций на Solana;","Недооценка, что может стать триггером стремительного роста."],"cons":["Испорченная репутация из-за банкротства FTX;","Наличие более технологичных и быстрорастущих конкурентов;","Излишне продолжительное нахождение в статусе перспективного проекта и «убийцы» Эфира, что несколько разочаровывает инвесторов."]}$b702$::jsonb,
