INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 58, 'paragraph',
       $b704${"text":"Несмотря на переход процедуры добычи Эфира на PoS-алгоритм в 2022 году, актив не стал менее популярным. ETH продолжает удерживать уверенное второе место по объему капитализации и интересу со стороны крипто-инвесторов после BTC. Это значит, что данная криптовалюта в 2026 году также должна находиться в портфеле: помимо заработка на росте курса, владельцы Эфириума могут зарабатывать на стейкинге – отправке актива в специализированные хранилища с вознаграждением. Именно по такому принципу сегодня добывается Ethereum после смены алгоритма с PoW на PoS. Для совместного заработка созданы специализированные пулы, позволяющие стейкать практически любой объем ETH.","html":"Несмотря на переход процедуры добычи Эфира на PoS-алгоритм в 2022 году, актив не стал менее популярным. ETH продолжает удерживать уверенное второе место по объему капитализации и интересу со стороны крипто-инвесторов после BTC. Это значит, что данная криптовалюта в 2026 году также должна находиться в портфеле: помимо заработка на росте курса, владельцы Эфириума могут зарабатывать на стейкинге – отправке актива в специализированные хранилища с вознаграждением. Именно по такому принципу сегодня добывается Ethereum после смены алгоритма с PoW на PoS. Для совместного заработка созданы специализированные пулы, позволяющие стейкать практически любой объем ETH."}$b704$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 59, 'paragraph',
       $b705${"text":"Не менее интересны планы разработчиков Ethereum: планируется ряд важных обновлений для увеличения скорости сети и расширения возможностей блокчейна. Также в 2024 году состоялось принятие спотового Ethereum-ETF, что привлекает новых инвесторов и становится триггером роста курса ETH.","html":"Не менее интересны планы разработчиков Ethereum: планируется ряд важных обновлений для увеличения скорости сети и расширения возможностей блокчейна. Также в 2024 году состоялось принятие спотового Ethereum-ETF, что привлекает новых инвесторов и становится триггером роста курса ETH."}$b705$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

