SELECT a.id, 62, 'pros_cons',
       $b708${"pros":["Вторая по капитализации криптовалюта в 2024 году;","Повышенное внимание к платформе многих разработчиков цифровых решений;","Реальное платежное средство для оплаты товаров и услуг в некоторых странах;","Высокая ликвидность, что позволяет проводить быстрые сделки на большинстве площадок;","Наиболее дорогие и известные NFT-коллекции созданы в сети Эфира."],"cons":["Негативное отношение майнеров из-за перехода на PoS;","Не самая выдающаяся скорость работы сети;","Высокие комиссии;","Проблемы с масштабированием, что в еще большей степени влияет на скорость транзакций;","Неограниченная эмиссия, что может привести к инфляции."]}$b708$::jsonb,
