INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 64, 'paragraph',
       $b710${"text":"В любые времена вне зависимости от рыночной ситуации Биткоин должен находиться в портфеле трейдера, инвестора или просто человека, желающего заработать в нише цифровых активов. BTC является фундаментальным форматом, вокруг которого строятся любые тенденции, прогнозы и активности: курс Bitcoin, доминация BTC, сложность сети Биткоина – все это основные метрики, которыми пользуются как майнеры, так и эксперты инвестирования. По сравнению с другими монетами, BTC отличается наименьшей волатильностью, что является гарантией сохранности средств даже в непростые рыночные времена.","html":"В любые времена вне зависимости от рыночной ситуации Биткоин должен находиться в портфеле трейдера, инвестора или просто человека, желающего заработать в нише цифровых активов. BTC является фундаментальным форматом, вокруг которого строятся любые тенденции, прогнозы и активности: курс Bitcoin, доминация BTC, сложность сети Биткоина – все это основные метрики, которыми пользуются как майнеры, так и эксперты инвестирования. По сравнению с другими монетами, BTC отличается наименьшей волатильностью, что является гарантией сохранности средств даже в непростые рыночные времена."}$b710$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 65, 'paragraph',
       $b711${"text":"Bitcoin можно рассматривать в качестве оптимального варианта для инвестирования не только ввиду своей капитализации и фундаментала, но еще из-за влияния халвинга. BTC – безальтернативное первое место рейтинга перспективных криптовалют в 2024–2025 годах.","html":"Bitcoin можно рассматривать в качестве оптимального варианта для инвестирования не только ввиду своей капитализации и фундаментала, но еще из-за влияния халвинга. BTC – безальтернативное первое место рейтинга перспективных криптовалют в 2024–2025 годах."}$b711$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

