INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 68, 'pros_cons',
       $b714${"pros":["Старейший и наиболее надежный цифровой актив;","Минимальная волатильность и подверженность спекулятивным факторам;","Ограниченная эмиссия, что создает эффект искусственного дефицита (такой актив всегда растет в цене);","Можно не только покупать для инвестиций, но и добывать с помощью майнинга;","Поддержка всеми криптовалютными инструментами и сервисами;","Мгновенные сделки из-за максимальной ликвидности на основных биржах и площадках;","Возможность оплаты товаров и услуг в некоторых странах."],"cons":["Из-за минимальной волатильности доходность актива уступает альтернативным монетам;","Растущая сложность майнинга, что снижает доходы тех, кто занимается добычей;","Сложная процедура вычисления, что вынуждает использовать дорогостоящее, ресурсоемкое и шумное оборудование."]}$b714$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

