INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 70, 'paragraph',
       $b716${"text":"Выбор монеты для майнинга – это не разовая задача, а динамический процесс, требующий учета множества параметров: от технических характеристик оборудования до глобальных рыночных трендов. В условиях высокой конкуренции и волатильности рынка наиболее успешными оказываются те майнеры, кто не полагается на удачу, а использует аналитику, регулярно пересматривает стратегию и опирается на проверенные данные.","html":"Выбор монеты для майнинга – это не разовая задача, а динамический процесс, требующий учета множества параметров: от технических характеристик оборудования до глобальных рыночных трендов. В условиях высокой конкуренции и волатильности рынка наиболее успешными оказываются те майнеры, кто не полагается на удачу, а использует аналитику, регулярно пересматривает стратегию и опирается на проверенные данные."}$b716$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 71, 'paragraph',
       $b717${"text":"Умение выбирать монеты с перспективой и грамотно подбирать под них оборудование позволяет не только сохранить рентабельность, но и выстраивать устойчивую модель дохода даже в условиях неопределенности. Информированность и гибкость – два столпа эффективного майнинга сегодня.","html":"Умение выбирать монеты с перспективой и грамотно подбирать под них оборудование позволяет не только сохранить рентабельность, но и выстраивать устойчивую модель дохода даже в условиях неопределенности. Информированность и гибкость – два столпа эффективного майнинга сегодня."}$b717$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshaya-kriptovalyuta-v-2024-godu-rejting-monet-dlya-investirovaniya';

