INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 2, 'paragraph',
       $b719${"text":"Мессенджер Телеграм является одной из самых популярных площадок для общения, знакомства с новостями и игр в криптовалютном мире. Именно здесь сосредоточено наиболее ощутимое количество проектов, имеющих отношение к цифровым активам. Проанализируем лучшие каналы о майнинге в Telegram – оценим информативность и качество проектов, узнаем об их преимуществах и недостатках, отметим особенности и отличительные черты наиболее интересных сообществ в TG.","html":"Мессенджер Телеграм является одной из самых популярных площадок для общения, знакомства с новостями и игр в криптовалютном мире. Именно здесь сосредоточено наиболее ощутимое количество проектов, имеющих отношение к цифровым активам. Проанализируем лучшие каналы о майнинге в Telegram – оценим информативность и качество проектов, узнаем об их преимуществах и недостатках, отметим особенности и отличительные черты наиболее интересных сообществ в TG."}$b719$::jsonb,
