INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 5, 'paragraph',
       $b722${"text":"Telegram стал не просто мессенджером, а полноценной информационной экосистемой. В криптосообществе он занимает особое место – здесь обсуждают курсы, новые ASIC-и, прошивки, проблемы с пулами, энергоценами, а также делятся лайфхаками по размещению оборудования и настройке.","html":"Telegram стал не просто мессенджером, а полноценной информационной экосистемой. В криптосообществе он занимает особое место – здесь обсуждают курсы, новые ASIC-и, прошивки, проблемы с пулами, энергоценами, а также делятся лайфхаками по размещению оборудования и настройке."}$b722$::jsonb,
