INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 12, 'list',
       $b729${"ordered":false,"items":["Оперативность. Новости, обновления и предупреждения (например, о падении сети или сбоях в работе пулов) публикуются практически мгновенно;","Комьюнити. Можно не только читать, но и общаться – в чатах, комментариях и приватных группах;","Конфиденциальность. Telegram сохраняет анонимность, что особенно важно в регионах с жестким регулированием криптовалют;","Доступ к «внутрянке». Часто инсайды, скидки, эксклюзивы и технические фишки появляются сначала в Телеграме;","Мобильность. Все, что нужно – смартфон с интернетом. Можно следить за ситуацией даже из дата-центра или склада."]}$b729$::jsonb,
