INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 16, 'rich_list',
       $b733${"ordered":false,"items":[{"title":"Регулярность публикаций","text":"Хороший канал публикует посты хотя бы несколько раз в неделю. Это говорит о том, что авторы следят за темой и поддерживают актуальность контента;"},{"title":"Тематика","text":"Одни каналы ориентированы на новичков, другие – на профи. Есть каналы по прошивкам, торговле б/у техникой, аналитике. Выбирайте в зависимости от своих задач: покупки, настройки, инвестиций, трейдинга или масштабирования;"},{"title":"Авторитетность","text":"Кто ведет канал? Это частное лицо, команда разработчиков, сервисная компания, агрегатор или продавец? Лучше отдавать предпочтение тем, кто имеет практический опыт, репутацию и не скрывает свою идентичность;"},{"title":"Прозрачность","text":"Если канал рекламирует сервисы, пулы или прошивки, это нормально – но важно, чтобы реклама была помечена и не маскировалась;"},{"title":"Комментарии и дискуссии","text":"Наличие обсуждений или связанного чата говорит о живом сообществе. Это огромный плюс: можно задать вопрос, узнать чужое мнение, попросить помощи."}]}$b733$::jsonb,
