INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 19, 'list',
       $b736${"ordered":false,"items":["Остерегайтесь фейковых розыгрышей. Если от вас требуют внести криптовалюту для участия в «розыгрыше асика» – это, скорее всего, обман;","Фейковые техподдержки. Мошенники могут дублировать каналы или выдавать себя за представителей брендов. Всегда проверяйте официальные ссылки;","Нереалистичные обещания. Фразы вроде «заработай 5000 рублей в день с телефона» или «автоматический облачный майнинг без вложений» – почти гарантированно ловушка;","Продажа оборудования с частных аккаунтов;","Проверяйте продавцов и каналы, где они публикуются. Лучше использовать каналы с репутацией и гарантами сделок."]}$b736$::jsonb,
