INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 27, 'paragraph',
       $b744${"text":"Канал от крупного и известного магазина по продаже техники для добычи криптовалют. Ресурс предлагает качественные новости мира майнинга – авторы контента фокусируют внимание именно на сегменте добычи, что позволяет получать профильную информацию. Ключевая особенность наполнения – длинные и подробные тексты, а также наглядная инфографика. Каждый пост дополняется авторской картинкой, содержащей немало полезной информации. Доля коммерческого контента незначительная, что приятно удивляет в рамках канала от магазина.","html":"Канал от крупного и известного магазина по продаже техники для добычи криптовалют. Ресурс предлагает качественные новости мира майнинга – авторы контента фокусируют внимание именно на сегменте добычи, что позволяет получать профильную информацию. Ключевая особенность наполнения – длинные и подробные тексты, а также наглядная инфографика. Каждый пост дополняется авторской картинкой, содержащей немало полезной информации. Доля коммерческого контента незначительная, что приятно удивляет в рамках канала от магазина."}$b744$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 28, 'paragraph',
       $b745${"text":"Проект ориентирован на тех, кто хочет знать новости именно о майнинге и предпочитает подробный формат повествования. Приверженцам поверхностного серфинга канал будет не интересен, как и для пользователей, ищущих новости о криптовалютах в целом – чувствуется профильная специализация контента, в результате чего количество подписчиков «Intelion Data Systems» остается стабильно небольшим.","html":"Проект ориентирован на тех, кто хочет знать новости именно о майнинге и предпочитает подробный формат повествования. Приверженцам поверхностного серфинга канал будет не интересен, как и для пользователей, ищущих новости о криптовалютах в целом – чувствуется профильная специализация контента, в результате чего количество подписчиков «Intelion Data Systems» остается стабильно небольшим."}$b745$::jsonb,
