INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 32, 'paragraph',
       $b749${"text":"Небольшой авторский канал о криптовалютах и майнинге, где акцент сделан именно на добыче цифровых активов. Создатель сочетает контент о личном опыте работы в данной индустрии со смежными новостями – нововведения бирж, актуальные тренды, игровые проекты и многое-многое другое. Канал ведется неформально – отсутствует единый фирменный стиль повествования, некоторые посты выходят без картинок. Однако знакомиться с информацией интересно и увлекательно.","html":"Небольшой авторский канал о криптовалютах и майнинге, где акцент сделан именно на добыче цифровых активов. Создатель сочетает контент о личном опыте работы в данной индустрии со смежными новостями – нововведения бирж, актуальные тренды, игровые проекты и многое-многое другое. Канал ведется неформально – отсутствует единый фирменный стиль повествования, некоторые посты выходят без картинок. Однако знакомиться с информацией интересно и увлекательно."}$b749$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 33, 'paragraph',
       $b750${"text":"Отдельно следует отметить личный опыт автора: ведется повествование о создании, использовании и обслуживании майнерской фермы – есть текстовые посты и видео, в которых подробно раскрывается заданная тематика. «Искусство Майнинга» – хороший пример авторского контента на тематику добычи криптовалют с сочетанием новостей из смежных направлений.","html":"Отдельно следует отметить личный опыт автора: ведется повествование о создании, использовании и обслуживании майнерской фермы – есть текстовые посты и видео, в которых подробно раскрывается заданная тематика. «Искусство Майнинга» – хороший пример авторского контента на тематику добычи криптовалют с сочетанием новостей из смежных направлений."}$b750$::jsonb,
