INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 37, 'paragraph',
       $b754${"text":"Канал с предельно простым названием, который полностью отражает его наполнение: автор является опытным майнером на асиках и картах, рассказывая о своей деятельности подписчикам. Полностью неформальная концепция позволяет знакомиться с контентом легко и непринужденно – данный концепт не надоедает и позволяет сохранять интерес. Иногда владелец ресурса дополняет посты о майнинге информацией о смежных вариантах деятельности, в числе которых крипто-игры, а также полезные инсайды от бирж, обменников и кошельков.","html":"Канал с предельно простым названием, который полностью отражает его наполнение: автор является опытным майнером на асиках и картах, рассказывая о своей деятельности подписчикам. Полностью неформальная концепция позволяет знакомиться с контентом легко и непринужденно – данный концепт не надоедает и позволяет сохранять интерес. Иногда владелец ресурса дополняет посты о майнинге информацией о смежных вариантах деятельности, в числе которых крипто-игры, а также полезные инсайды от бирж, обменников и кошельков."}$b754$::jsonb,
