SELECT a.id, 38, 'paragraph',
       $b755${"text":"«Майнинг криптовалют» – это крайне полезный канал для практикующих и начинающих майнеров. Здесь можно получить ценную информацию, которая проанализирована на практике. Контент помогает избежать типичных ошибок, а также найти решение часто возникающих проблем – всем этим делится автор со своими подписчиками.","html":"«Майнинг криптовалют» – это крайне полезный канал для практикующих и начинающих майнеров. Здесь можно получить ценную информацию, которая проанализирована на практике. Контент помогает избежать типичных ошибок, а также найти решение часто возникающих проблем – всем этим делится автор со своими подписчиками."}$b755$::jsonb,
