INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 42, 'paragraph',
       $b759${"text":"Авторский канал майнера, добывающего криптовалюту с помощью процессоров и видеокарт. Кроме этого, перечень тематик контента включает многие смежные направления – игры, биржевые новости, а также другие сегменты мира цифровых активов. Формат подачи информации воспринимается легко за счет непринужденного стиля общения автора с подписчиками. Канал имеет свою базу преданных читателей, которые проявляют высокую активность.","html":"Авторский канал майнера, добывающего криптовалюту с помощью процессоров и видеокарт. Кроме этого, перечень тематик контента включает многие смежные направления – игры, биржевые новости, а также другие сегменты мира цифровых активов. Формат подачи информации воспринимается легко за счет непринужденного стиля общения автора с подписчиками. Канал имеет свою базу преданных читателей, которые проявляют высокую активность."}$b759$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 43, 'paragraph',
       $b760${"text":"Проект «USMFOX MINING | Майнинг и криптовалюта» может понравиться не всем потенциальным подписчикам, так как тематика контента основывается на тех проектах, в которых участвует сам автор. Прежде всего, это майнинг на GPU, актуальные игровые активности и другие продукты мира цифровой индустрии.","html":"Проект «USMFOX MINING | Майнинг и криптовалюта» может понравиться не всем потенциальным подписчикам, так как тематика контента основывается на тех проектах, в которых участвует сам автор. Прежде всего, это майнинг на GPU, актуальные игровые активности и другие продукты мира цифровой индустрии."}$b760$::jsonb,
