INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 54, 'paragraph',
       $b771${"text":"Простой и неформальный подход к ведению авторского блога, где упор делается не на оформление постов, а их содержание. Создатель рассказывает о своей деятельности в сфере майнинга и криптовалют, делится опытом и отвечает на вопросы подписчиков. При этом Николай может просто сфотографировать монитор своего компьютера (вместо того, чтобы сделать скриншот), забыть о центровке фотографии или пренебречь оформлением текста.","html":"Простой и неформальный подход к ведению авторского блога, где упор делается не на оформление постов, а их содержание. Создатель рассказывает о своей деятельности в сфере майнинга и криптовалют, делится опытом и отвечает на вопросы подписчиков. При этом Николай может просто сфотографировать монитор своего компьютера (вместо того, чтобы сделать скриншот), забыть о центровке фотографии или пренебречь оформлением текста."}$b771$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 55, 'paragraph',
       $b772${"text":"Ключевая ценность этого несколько небрежного канала – информация. Временами автор делится настоящими лайфхаками, помогая решить сложные технические вопросы. Это самый что ни есть авторский формат ведения блога на тематику цифровых активов со всеми своими особенностями и нюансами. Если вы не акцентируете внимание на оформлении, подписка на Николая позволит найти немало полезных данных: количество постов действительно впечатляет.","html":"Ключевая ценность этого несколько небрежного канала – информация. Временами автор делится настоящими лайфхаками, помогая решить сложные технические вопросы. Это самый что ни есть авторский формат ведения блога на тематику цифровых активов со всеми своими особенностями и нюансами. Если вы не акцентируете внимание на оформлении, подписка на Николая позволит найти немало полезных данных: количество постов действительно впечатляет."}$b772$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

