INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 60, 'paragraph',
       $b777${"text":"Авторский канал самого известного русскоговорящего майнера на видеокартах. Сергей «Соленый» хорошо знаком майнерскому сообществу – помимо канала в ТГ, автор публикует большие объемы полезного контента на Youtube. Именно этого человека можно назвать настоящим экспертом в области майнинга на GPU: посты выходят нечасто, однако, объем полезной информации целиком компенсирует данный факт.","html":"Авторский канал самого известного русскоговорящего майнера на видеокартах. Сергей «Соленый» хорошо знаком майнерскому сообществу – помимо канала в ТГ, автор публикует большие объемы полезного контента на Youtube. Именно этого человека можно назвать настоящим экспертом в области майнинга на GPU: посты выходят нечасто, однако, объем полезной информации целиком компенсирует данный факт."}$b777$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 61, 'paragraph',
       $b778${"text":"«Новости от Соленого» имеют свою базу преданных поклонников: подписчики активно общаются в комментариях, поэтому актуальные данные есть не только в контенте, но и в пользовательском фидбэке. В последние годы имя «Соленого» уже стало нарицательным, поэтому каждый майнер на видеокартах должен быть подписчиком этого канала. Правда, придется привыкнуть к своеобразному формату публикаций, например, автор может снять видео с сигаретой в руке или не самым культурным образом высказаться о чем-либо.","html":"«Новости от Соленого» имеют свою базу преданных поклонников: подписчики активно общаются в комментариях, поэтому актуальные данные есть не только в контенте, но и в пользовательском фидбэке. В последние годы имя «Соленого» уже стало нарицательным, поэтому каждый майнер на видеокартах должен быть подписчиком этого канала. Правда, придется привыкнуть к своеобразному формату публикаций, например, автор может снять видео с сигаретой в руке или не самым культурным образом высказаться о чем-либо."}$b778$::jsonb,
