INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 66, 'paragraph',
       $b783${"text":"Канал о майнинге с наибольшим количеством участников в РУ-сегменте, однако, данное значение не должно вводить в заблуждение: аналитика позволяет сделать выводы, что большая доля участников была приведена с помощью накрутки. Тем не менее, активных читателей и пользователей также немало, как и объем полезной информации на канале. Проект принадлежит одноименному магазину техники для майнинга – продавец хорошо знаком российским участникам отрасли цифровых активов.","html":"Канал о майнинге с наибольшим количеством участников в РУ-сегменте, однако, данное значение не должно вводить в заблуждение: аналитика позволяет сделать выводы, что большая доля участников была приведена с помощью накрутки. Тем не менее, активных читателей и пользователей также немало, как и объем полезной информации на канале. Проект принадлежит одноименному магазину техники для майнинга – продавец хорошо знаком российским участникам отрасли цифровых активов."}$b783$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 67, 'paragraph',
       $b784${"text":"Предложенных форматов контента немного: чаще всего авторы канала знакомят подписчиков с техникой (как правило, с помощью видеообзоров на самые разные темы) и публикуют актуальный прайс-лист на предлагаемую аппаратуру. Но при всех своих противоречиях, за ресурсом «Mining Center» в Телеграм следить интересно: краткие, но емкие обзоры содержат множество полезных данных. А обновляемые ежедневно цены позволяют оценить возможные инвестиции практически в онлайн-режиме.","html":"Предложенных форматов контента немного: чаще всего авторы канала знакомят подписчиков с техникой (как правило, с помощью видеообзоров на самые разные темы) и публикуют актуальный прайс-лист на предлагаемую аппаратуру. Но при всех своих противоречиях, за ресурсом «Mining Center» в Телеграм следить интересно: краткие, но емкие обзоры содержат множество полезных данных. А обновляемые ежедневно цены позволяют оценить возможные инвестиции практически в онлайн-режиме."}$b784$::jsonb,
