INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 72, 'paragraph',
       $b789${"text":"Один из крупнейших магазинов по продаже техники для майнинга ответственно подошел к ведению своего канала в Telegram. Профессиональный формат подачи информации, фирменный стиль постов, качественная графика – все это делает наполнение ресурса полезным и информативным. А еще здесь нет данных о сомнительных форматах работы на крипторынке (например, «тапалки» для телефонов): авторы концентрируют внимание исключительно на майнинге и всему тому, что с ним связано.","html":"Один из крупнейших магазинов по продаже техники для майнинга ответственно подошел к ведению своего канала в Telegram. Профессиональный формат подачи информации, фирменный стиль постов, качественная графика – все это делает наполнение ресурса полезным и информативным. А еще здесь нет данных о сомнительных форматах работы на крипторынке (например, «тапалки» для телефонов): авторы концентрируют внимание исключительно на майнинге и всему тому, что с ним связано."}$b789$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

