SELECT a.id, 73, 'paragraph',
       $b790${"text":"Канал действительно ведется профессионально и вызывает уважение: проект выглядит респектабельно и формирует доверие к магазину. Качество аудитории также свидетельствует о том, что подписчики интересуются тематикой и активно знакомятся с новыми постами.","html":"Канал действительно ведется профессионально и вызывает уважение: проект выглядит респектабельно и формирует доверие к магазину. Качество аудитории также свидетельствует о том, что подписчики интересуются тематикой и активно знакомятся с новыми постами."}$b790$::jsonb,
