INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 78, 'paragraph',
       $b795${"text":"Как бы парадоксально это не выглядело, но на первом месте рейтинга расположился канал с наименьшим количеством подписчиков среди всех участников нашего ТОП-а. Причина подобного явления кроется в контенте, который публикуется на канале: это действительно качественный и полезный материал, дополненный эффектной инфографикой. Возникает желание рассматривать картинки даже дольше, чем читать текст – именно подобный подход вызывает доверие и уважение.","html":"Как бы парадоксально это не выглядело, но на первом месте рейтинга расположился канал с наименьшим количеством подписчиков среди всех участников нашего ТОП-а. Причина подобного явления кроется в контенте, который публикуется на канале: это действительно качественный и полезный материал, дополненный эффектной инфографикой. Возникает желание рассматривать картинки даже дольше, чем читать текст – именно подобный подход вызывает доверие и уважение."}$b795$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

INSERT INTO article_blocks (article_id, position, type, payload, anchor)
SELECT a.id, 79, 'paragraph',
       $b796${"text":"Несмотря на то, что ресурс принадлежит магазину по продаже техники, во время знакомства с каналом не создается впечатления, что вам хотят что-то продать: коммерческая интеграция осуществляется максимально мягким способом. Показатели вовлеченности подписчиков также вызывают доверие: участники активно читают посты и оставляют реакции.","html":"Несмотря на то, что ресурс принадлежит магазину по продаже техники, во время знакомства с каналом не создается впечатления, что вам хотят что-то продать: коммерческая интеграция осуществляется максимально мягким способом. Показатели вовлеченности подписчиков также вызывают доверие: участники активно читают посты и оставляют реакции."}$b796$::jsonb,
       NULL
FROM articles a WHERE a.slug = 'luchshie-kanaly-o-majninge-v-telegram-top-10';

